head.b:skin:
/* CSS Reset & Essential Theme Variables */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  background-color: #f8fafc;
  color: #1e293b;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a {
  text-decoration: none;
  color: inherit;
}
/* Sembunyikan elemen bawaan blogspot yang tidak diperlukan */
.blogger-hidden-section {
  display: none !important;
}
#navbar-iframe {
  display: none !important;
  height: 0 !important;
  visibility: hidden !important;
}
/* Scrollbar halus */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: #f1f5f9;
}
::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}

body.script:
//
(function() {
  var STORAGE_KEY = 'ips_maestro_blogger_key';

  window.ipsThemeOpenKeyModal = function() {
    var modal = document.getElementById('ips-theme-modal-key');
    if (modal) {
      modal.style.display = 'flex';
      var saved = localStorage.getItem(STORAGE_KEY) || '';
      document.getElementById('ips-theme-input-api-key').value = saved;
    }
  };

  window.ipsThemeCloseKeyModal = function() {
    var modal = document.getElementById('ips-theme-modal-key');
    if (modal) modal.style.display = 'none';
  };

  window.ipsThemeSaveKey = function() {
    var key = (document.getElementById('ips-theme-input-api-key').value || '').trim();
    if (!key) {
      alert('Kunci API tidak boleh kosong.');
      return;
    }
    localStorage.setItem(STORAGE_KEY, key);
    window.ipsThemeUpdateKeyBadge();
    window.ipsThemeCloseKeyModal();
    alert('Kunci API Gemini berhasil disimpan!');
  };

  window.ipsThemeUpdateKeyBadge = function() {
    var badge = document.getElementById('ips-theme-key-badge');
    var key = localStorage.getItem(STORAGE_KEY);
    if (badge) {
      if (key && key.length > 5) {
        badge.innerText = 'API Aktif (' + key.substring(0, 4) + '...)';
      } else {
        badge.innerText = 'Setel Kunci API Gemini';
      }
    }
  };

  window.ipsThemeSwitchTab = function(tabId) {
    var tabs = ['rpp', 'lkpd', 'soal', 'chatbot'];
    tabs.forEach(function(t) {
      var view = document.getElementById('ips-theme-view-' + t);
      var btn = document.getElementById('ips-theme-tab-' + t);
      if (view) view.style.display = (t === tabId) ? 'block' : 'none';
      if (btn) {
        if (t === tabId) {
          btn.style.background = '#4f46e5';
          btn.style.color = '#ffffff';
        } else {
          btn.style.background = 'transparent';
          btn.style.color = '#64748b';
        }
      }
    });
  };

  async function callGemini(prompt, systemPrompt) {
    var key = localStorage.getItem(STORAGE_KEY);
    if (!key) {
      window.ipsThemeOpenKeyModal();
      throw new Error('Kunci API Gemini diperlukan. Silakan masukkan Kunci API Anda di jendela pengaturan.');
    }

    var url = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=' + encodeURIComponent(key);
    var payload = {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.7, maxOutputTokens: 8192 }
    };
    if (systemPrompt) {
      payload.systemInstruction = { parts: [{ text: systemPrompt }] };
    }

    var res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    var data = await res.json();
    if (!res.ok) {
      throw new Error(data.error ? data.error.message : 'Terjadi kendala pada Google Gemini API.');
    }

    if (data.candidates && data.candidates[0]?.content?.parts[0]?.text) {
      return data.candidates[0].content.parts[0].text;
    }
    throw new Error('Respon AI kosong.');
  }

  function renderMarkdown(md) {
    if (window.marked && window.marked.parse) {
      return window.marked.parse(md);
    }
    return md.replace(/\n/g, '<br/>');
  }

  window.ipsThemeGenerateRPP = async function() {
    var grade = document.getElementById('ips-theme-rpp-grade').value;
    var model = document.getElementById('ips-theme-rpp-model').value;
    var topic = document.getElementById('ips-theme-rpp-topic').value;
    if (!topic) { alert('Silakan masukkan topik materi.'); return; }

    var btn = document.getElementById('ips-theme-btn-gen-rpp');
    var resBox = document.getElementById('ips-theme-rpp-res-box');
    var out = document.getElementById('ips-theme-rpp-output');

    btn.disabled = true;
    btn.innerText = '⏳ Menyusun RPP...';

    try {
      var prompt = 'Buatkan Modul Ajar / RPP Kurikulum Merdeka mata pelajaran IPS SMP Kelas ' + grade + ' (Fase D) dengan topik "' + topic + '" menggunakan model pembelajaran "' + model + '". Lengkapi dengan: Capaian Pembelajaran, Tujuan Pembelajaran, Pemahaman Bermakna, Pertanyaan Pemantik, Langkah Kegiatan Pembelajaran Berdiferensiasi (Pendahuluan, Inti, Penutup), Asesmen (Diagnostik, Formatif, Sumatif), dan Refleksi Guru & Siswa. Format dalam Markdown terstruktur.';
      var sys = 'Anda adalah konsultan ahli Kurikulum Merdeka dan penyusun perangkat ajar IPS SMP Maestro karya Catur Pamungkas, S.Pd.,Gr. (toer.my.id).';
      var text = await callGemini(prompt, sys);

      out.innerHTML = renderMarkdown(text);
      resBox.style.display = 'block';
    } catch(err) {
      alert(err.message);
    } finally {
      btn.disabled = false;
      btn.innerText = '✨ Susun RPP Otomatis';
    }
  };

  window.ipsThemeGenerateLKPD = async function() {
    var grade = document.getElementById('ips-theme-lkpd-grade').value;
    var type = document.getElementById('ips-theme-lkpd-type').value;
    var topic = document.getElementById('ips-theme-lkpd-topic').value;
    if (!topic) { alert('Silakan masukkan topik LKPD.'); return; }

    var btn = document.getElementById('ips-theme-btn-gen-lkpd');
    var resBox = document.getElementById('ips-theme-lkpd-res-box');
    var out = document.getElementById('ips-theme-lkpd-output');

    btn.disabled = true;
    btn.innerText = '⏳ Membuat LKPD...';

    try {
      var prompt = 'Buatkan Lembar Kerja Peserta Didik (LKPD) Kurikulum Merdeka IPS SMP Kelas ' + grade + ' topik "' + topic + '" dengan jenis aktivitas "' + type + '". Sertakan: Identitas LKPD, Petunjuk Kerja, Stimulus Wacana/Kasus Nyata Kontekstual, Pertanyaan Analitis Pemecahan Masalah, Tabel Lembar Eksplorasi Siswa, dan Rubrik Penilaian Terperinci. Format dalam Markdown terstruktur.';
      var sys = 'Anda adalah perancang lembar kerja peserta didik IPS SMP Kurikulum Merdeka Maestro karya Catur Pamungkas, S.Pd.,Gr. (toer.my.id).';
      var text = await callGemini(prompt, sys);

      out.innerHTML = renderMarkdown(text);
      resBox.style.display = 'block';
    } catch(err) {
      alert(err.message);
    } finally {
      btn.disabled = false;
      btn.innerText = '✨ Susun LKPD Siswa';
    }
  };

  window.ipsThemeGenerateSoal = async function() {
    var grade = document.getElementById('ips-theme-soal-grade').value;
    var type = document.getElementById('ips-theme-soal-type').value;
    var topic = document.getElementById('ips-theme-soal-topic').value;
    if (!topic) { alert('Silakan masukkan materi soal.'); return; }

    var btn = document.getElementById('ips-theme-btn-gen-soal');
    var resBox = document.getElementById('ips-theme-soal-res-box');
    var out = document.getElementById('ips-theme-soal-output');

    btn.disabled = true;
    btn.innerText = '⏳ Merancang Soal HOTS...';

    try {
      var prompt = 'Buatkan Bank Soal HOTS (High Order Thinking Skills - C4 sampai C6) mata pelajaran IPS SMP Kelas ' + grade + ' topik "' + topic + '" dengan bentuk soal "' + type + '". Sertakan: Kisi-kisi asesmen, stimulus wacana berita/kasus, butir soal HOTS, kunci jawaban, dan pembahasan mendalam serta rubrik penskoran. Format dalam Markdown rapi.';
      var sys = 'Anda adalah evaluator dan penyusun instrumen asesmen HOTS IPS SMP Maestro karya Catur Pamungkas, S.Pd.,Gr. (toer.my.id).';
      var text = await callGemini(prompt, sys);

      out.innerHTML = renderMarkdown(text);
      resBox.style.display = 'block';
    } catch(err) {
      alert(err.message);
    } finally {
      btn.disabled = false;
      btn.innerText = '✨ Rancang Soal HOTS';
    }
  };

  window.ipsThemeSendChat = async function() {
    var inp = document.getElementById('ips-theme-chat-input');
    var log = document.getElementById('ips-theme-chat-log');
    var btn = document.getElementById('ips-theme-btn-chat');
    var msg = (inp.value || '').trim();
    if (!msg) return;

    var userDiv = document.createElement('div');
    userDiv.style.cssText = 'background: #4f46e5; color: #ffffff; padding: 10px 14px; border-radius: 12px; font-size: 13px; line-height: 1.5; max-width: 85%; align-self: flex-end;';
    userDiv.innerText = msg;
    log.appendChild(userDiv);
    inp.value = '';
    log.scrollTop = log.scrollHeight;

    btn.disabled = true;
    btn.innerText = 'Mengetik...';

    try {
      var sys = 'Anda adalah asisten cerdas guru IPS SMP Maestro karya Catur Pamungkas, S.Pd.,Gr. (toer.my.id). Berikan jawaban yang ramah, solutif, pedagogis, dan berbasis Kurikulum Merdeka.';
      var reply = await callGemini(msg, sys);

      var botDiv = document.createElement('div');
      botDiv.style.cssText = 'background: #ffffff; color: #1e293b; border: 1px solid #cbd5e1; padding: 12px 14px; border-radius: 12px; font-size: 13px; line-height: 1.6; max-width: 85%; align-self: flex-start;';
      botDiv.innerHTML = renderMarkdown(reply);
      log.appendChild(botDiv);
      log.scrollTop = log.scrollHeight;
    } catch(err) {
      var errDiv = document.createElement('div');
      errDiv.style.cssText = 'background: #fee2e2; color: #991b1b; padding: 8px 12px; border-radius: 10px; font-size: 12px; max-width: 85%;';
      errDiv.innerText = 'Gagal: ' + err.message;
      log.appendChild(errDiv);
    } finally {
      btn.disabled = false;
      btn.innerText = 'Kirim';
    }
  };

  window.ipsThemeCopy = function(id) {
    var el = document.getElementById(id);
    if (!el) return;
    navigator.clipboard.writeText(el.innerText).then(function() {
      alert('Teks berhasil disalin ke clipboard!');
    });
  };

  window.ipsThemeDownloadWord = function(id, filename) {
    var el = document.getElementById(id);
    if (!el) return;
    var content = el.innerHTML;
    var html = '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="utf-8"><title>' + filename + '</title><style>body{font-family:Calibri,sans-serif;font-size:11pt;line-height:1.25;} h1,h2,h3{color:#0f172a;} table{border-collapse:collapse;width:100%;} th,td{border:1px solid #94a3b8;padding:6px 10px;}</style></head><body>' + content + '<br><hr><p style="font-size:9pt;color:#64748b;text-align:center;">Disusun dengan IPS Maestro • Karya Catur Pamungkas, S.Pd.,Gr. (toer.my.id) • Saluran WA: https://whatsapp.com/channel/0029Vb6R2Ny2v1J1dll5Mq27</p></body></html>';
    var blob = new Blob(['\ufeff', html], { type: 'application/msword' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = filename + '_' + new Date().toISOString().slice(0, 10) + '.doc';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  // Init badge saat dimuat
  window.ipsThemeUpdateKeyBadge();
})();
//
